import{_ as i,l as o,o as e,c as l,v as t,p as n,x as s,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"行大小与扇区缓存","description":"","frontmatter":{"title":"行大小与扇区缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/line-size-sector.md","filePath":"cs/line-size-sector.md","lastUpdated":1789023840000}'),p={name:"cs/line-size-sector.md"};function E(A,a,m,_,B,C){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="行大小与扇区缓存" tabindex="-1">行大小与扇区缓存 <a class="header-anchor" href="#行大小与扇区缓存" aria-label="Permalink to &quot;行大小与扇区缓存&quot;">​</a></h1><div class="epigraph"><p>行太短：强制缺失多、标签开销大；行太长：假共享与无用传输多。扇区让标签仍按大行走，有效数据可以只填其中几片。</p><footer>—— 据 Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/cache-compression">上一课</a> 在固定 64B 几何里挤信息。行大小本身是更早的旋钮：空间局部性希望大行，<a href="/cs/false-sharing">假共享</a> 与带宽希望小行。本课不重做 BDI。缺口是<strong>选行大小，以及扇区缓存：标签粒度与传输粒度分开。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>32B 行：指针追逐可能刚好，顺序扫描要四倍缺失。128B 行：一次 miss 拉更多字节，预取器压力下降，但多核下两个变量同行的概率上升，一致性作废更频。缺口不是分区，而是<strong>承认单一粒度难以两头讨好，用扇区在大标签块里只验证/只传输部分。</strong></p><p><span class="marginnote">扇区：例如 128B 逻辑行分成 4 个 32B，每片独立 valid。缺失可以只填被 touch 的扇区，其余稍后填或永不填。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选行：对目标工作负载量空间局部性跨度与多核写密度。扇区：miss 时按扇区发总线事务；标签命中但扇区 invalid 算 sector miss，延迟类似短行 miss 但标签已在。写回可以只回脏扇区。</p>',8)),(e(),n(h,null,{default:s(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAG%5B%22%E5%A4%A7%E8%A1%8C%E6%A0%87%E7%AD%BE%E5%91%BD%E4%B8%AD%22%5D%20--%3E%20SEC%5B%22%E6%89%87%E5%8C%BA%20valid%20%E4%BD%8D%22%5D%0A%20%20SEC%20--%3E%7C%22%E8%AF%A5%E7%89%87%E6%9C%89%E6%95%88%22%7C%20HIT%5B%22%E7%9C%9F%E5%91%BD%E4%B8%AD%22%5D%0A%20%20SEC%20--%3E%7C%22%E8%AF%A5%E7%89%87%E6%97%A0%E6%95%88%22%7C%20SM%5B%22%E6%89%87%E5%8C%BA%E7%BC%BA%E5%A4%B1%EF%BC%8C%E5%8F%AA%E5%8F%96%E8%AF%A5%E7%89%87%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>强制缺失次数随行增大而降，传输字节与假共享上升。<a href="/cs/stride-stream-prefetch">预取</a> 在大行上 \\(\\Delta\\) 以行为单位，过粗。压缩与扇区可组合：压缩后的槽仍对应逻辑行。目录项通常仍按全行，扇区是 data 路径优化。</p><p>指令 cache 往往用较大行：顺序取指的空间局部性极强，假共享几乎不存在。数据 cache 更纠结：指针结构要短行，数组扫描要长行，所以扇区主要出现在 D 侧与 LLC。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GPU 的 sector/cache line 配置当 CPU 的默认。也不提前把伪共享写完整课，只点名行越大越容易伪共享。写合并缓冲处理的是 store 的字节合并，粒度更细，下一课。</p><p>后课默认：传输不必整行；扇区把标签与数据粒度拆开。连续的窄 store 可以在进 cache 前先合并。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>行大小权衡强制缺失与假共享/带宽。</li><li>扇区缓存让一次标签覆盖多片，按需传输。</li><li>写合并在 store 路径上合并窄写，是下一课。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const D=i(p,[["render",E]]);export{u as __pageData,D as default};
